exercises.solution:
F_SKUS: dict[str, int] = {f"F{n}": n for n in (2, 4, 8, 16, 32, 64, 128, 256, 512, 1024, 2048)}


def cu_hours(sku: str, hours: float) -> float:
    """Capacity-unit hours for running an F SKU capacity.

    Args:
        sku: F SKU name such as "F64".
        hours: Hours the capacity runs.

    Returns:
        CUs multiplied by hours.

    Raises:
        ValueError: For an unknown SKU or negative hours.
    """
    if sku not in F_SKUS:
        raise ValueError(f"unknown F SKU: {sku!r}")
    if hours < 0:
        raise ValueError("hours must not be negative")
    return float(F_SKUS[sku] * hours)
